    public static List<String> materialsForSpecies(String species) {
        if (species == null) return Collections.emptyList();
        List<String> direct = DATE_BASE.get(species);
        if (direct != null) return direct;
        for (Map.Entry<String,List<String>> e : DATE_BASE.entrySet()) {
            if (e.getKey().equalsIgnoreCase(species)) return e.getValue();
        }
        return Collections.emptyList();
    }
